#!/usr/bin/env bash
# Visual grounding in video — find when and where an object appears in a clip
curl -s https://api.articul8.ai/bivia/ground \
  -H "Authorization: Bearer ${A8_API_KEY:?Set A8_API_KEY}" \
  -H "Content-Type: application/json" \
  -d '{
    "video": {
      "b64": "",
      "mime": "video/mp4"
    },
    "question": "the red square",
    "kind": "object"
  }' | python3 -m json.tool
